    wire signed [11:0] k1 = e1 + 12'sd149;                  // binary32 subnormal: F = P * 2^k1
    wire [11:0] nk1 = -k1;
    reg  [15:0] rp;
    reg  signed [11:0] re;
    reg         rs, rz, rkneg;
    reg  [4:0]  rkl, rkr;
    always @(posedge clk) begin
        rp <= ma * mw;
        re <= e1;
        rs <= w[15];
        rz <= az || wz;
        rkneg <= k1[11];
        rkl <= k1[4:0];
        rkr <= (nk1 > 12'd17) ? 5'd17 : nk1[4:0];
    end

    // -- stage 2 --------------------------------------------------------------------
    reg  [4:0]  lz0;
    integer kq;
    always @* begin
        lz0 = 5'd16;
        for (kq = 0; kq < 16; kq = kq + 1) if (rp[kq]) lz0 = 5'd15 - kq[4:0];
    end
    wire [4:0]         lz;
    wire [15:0]        p2;
    wire signed [11:0] e2;
    wire               s2s, s2z, s2kneg;
    wire [4:0]         s2kl, s2kr;
    ot_hdc_delay #(.W(5 + 16 + 12 + 3 + 10), .D((ML >= 5) ? 1 : 0)) u_cut2 (.clk(clk), .rst_n(1'b1),
        .d({lz0, rp, re, rs, rz, rkneg, rkl, rkr}), .q({lz, p2, e2, s2s, s2z, s2kneg, s2kl, s2kr}));
    wire [15:0]        pn = p2 << lz;
    wire signed [11:0] be = e2 + 12'sd142 - $signed({7'd0, lz});   // 15 - lz + e1 + 127
    wire [32:0]        xr = {p2, 17'd0} >> s2kr;
    wire [23:0]        fl = {8'd0, p2} << s2kl;
    reg  [15:0] s_pn;
    reg  [7:0]  s_be;
    reg         s_nrm, s_o32, s_zero, s_sign, s_kneg;
    reg  [16:0] s_q;               // subnormal (right shift): integer part
    reg         s_g, s_st;
    reg  [23:0] s_fl;              // subnormal (left shift): exact
    always @(posedge clk) begin
        s_pn <= pn;
        s_be <= be[7:0];
        s_nrm <= (be >= 12'sd1);
        s_o32 <= !s2z && (p2 != 16'd0) && (be >= 12'sd255);
        s_zero <= s2z || (p2 == 16'd0);
        s_sign <= s2s;
        s_kneg <= s2kneg;
